import {
  EXTERNAL_FLOOD_PRA_SR_CATALOG,
  type ExternalFloodAnalysisRecord,
  type ExternalFloodPRA,
  type ExternalFloodPraInterfaceRecord,
  type ExternalFloodPraInterfaceTransferItem,
} from "interfaces-mef-types/external-flood/external-flood-pra";
import { synchronizeExternalFloodPraDerivedRegisters } from "interfaces-mef-types/external-flood/external-flood-pra-validation";
import { createBlankExternalFloodPra } from "../../external-flood-pra-workbooks/blank-external-flood-pra";
import { createHazardConditionedMethodModels } from "./hazard-conditioned-method-model-seed";

type Variant = "HTGR" | "SFR";

const owner = "External Hazards PRA Team";
const srs = (...ids: string[]) => ids.map((sr) => ({ sr, hlr: EXTERNAL_FLOOD_PRA_SR_CATALOG[sr]?.hlr ?? "A" as const }));

function rec(variant: Variant, code: string, name: string, description: string, basis: string, implementsSrs: string[] = []): ExternalFloodAnalysisRecord {
  return {
    uuid: `${variant}-XF-${code}`,
    code: `XF-${code}`,
    name,
    description,
    basis,
    owner,
    status: "APPROVED",
    evidenceRefs: [`${variant}-XF-EV-001`, `${variant}-XF-EV-006`],
    relatedRefs: [],
    assumptionRefs: [],
    implementsSrs: srs(...implementsSrs),
  };
}

function recordWith<T extends Record<string, unknown>>(variant: Variant, code: string, name: string, description: string, basis: string, values: T, implementsSrs: string[] = []): ExternalFloodAnalysisRecord & T {
  return { ...rec(variant, code, name, description, basis, implementsSrs), ...values };
}

function field(record: ExternalFloodAnalysisRecord, key: string): unknown {
  return (record as unknown as Record<string, unknown>)[key];
}

function textField(record: ExternalFloodAnalysisRecord, key: string, fallback = "Not specified"): string {
  const value = field(record, key);
  return typeof value === "string" && value.length > 0 ? value : fallback;
}

function listField(record: ExternalFloodAnalysisRecord, key: string): string[] {
  const value = field(record, key);
  return Array.isArray(value) ? value.map(String) : [];
}

function numberField(record: ExternalFloodAnalysisRecord, key: string): number {
  const value = field(record, key);
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function readable(value: string): string {
  return value.toLowerCase().replace(/_/g, " ").replace(/(^|\s)\S/g, (letter) => letter.toUpperCase());
}

function scientific(value: number): string {
  return value.toExponential(2).replace("e", "E");
}

function populateDocumentation(mef: ExternalFloodPRA, variant: Variant): void {
  const sections = [
    mef.analysisBasis, mef.hazardScreening, mef.siteFloodModel, mef.localIntensePrecipitationAnalysis,
    mef.riverineFloodAnalysis, mef.damAndImpoundmentAnalysis, mef.surgeSeicheTsunamiAnalysis,
    mef.hazardIntegration, mef.preliminaryPlantResponse, mef.plantInvestigation,
    mef.sscScreeningAndFragilityBasis, mef.floodFragilityAnalysis, mef.scenarioDevelopment,
    mef.plantResponseModel, mef.humanReliabilityAnalysis, mef.eventSequenceQuantification, mef.technicalClosure,
  ];
  for (const [index, section] of sections.entries()) {
    section.documentation.processDescription = `The controlled ${variant} External Flood PRA process develops this section from qualified inputs, analyst calculations, independent checks, and configuration-controlled model records.`;
    section.documentation.inputsDescription = "Inputs include controlled drawings, survey elevations, hydrometeorological data, baseline PRA records, plant investigations, calculations, procedures, and operating experience.";
    section.documentation.methodsDescription = "The method applies the applicable XFHA, XFFR, and XFPR supporting requirements with explicit uncertainty, dependency, spatial, temporal, and traceability treatment.";
    section.documentation.resultsDescription = "Results are complete, independently checked, linked to downstream consumers, and included in the released External Flood PRA baseline.";
    section.documentation.limitations = ["Values are representative demonstration data and are not suitable for licensing use."];
    section.documentation.supportingDocumentRefs = [`${variant}-XF-EV-001`, `${variant}-XF-EV-${String((index % 10) + 2).padStart(3, "0")}`];
    section.documentation.traceabilityLinks = [{
      uuid: `${variant}-XF-TRACE-DOC-${String(index + 1).padStart(2, "0")}`,
      requirementRef: index < 9 ? "XFHA-G4" : index < 12 ? "XFFR-F3" : "XFPR-G1",
      inputRefs: section.documentation.supportingDocumentRefs,
      modelRefs: [], resultRefs: [], documentationRefs: [section.documentation.uuid],
    }];
  }
}

function transfer(
  variant: Variant,
  code: string,
  name: string,
  sourceModelRef: string,
  destinationRefs: string[],
  values: string[],
  evidenceRefs: string[] = [`${variant}-XF-EV-009`],
): ExternalFloodPraInterfaceTransferItem {
  return {
    uuid: `${variant}-XF-INT-${code}`,
    name,
    recordRef: code,
    sourceModelRef,
    destinationRefs,
    values,
    evidenceRefs,
    status: "CONTROLLED",
  };
}

function interfaceRecord(
  variant: Variant,
  code: string,
  elementCode: ExternalFloodPraInterfaceRecord["technicalElementCode"],
  elementName: string,
  direction: "INPUT" | "OUTPUT",
  payloadType: ExternalFloodPraInterfaceRecord["payloadType"],
  role: string,
  columns: string[],
  transferItems: ExternalFloodPraInterfaceTransferItem[],
): ExternalFloodPraInterfaceRecord {
  const producer = direction === "INPUT" ? elementCode : "XF";
  const consumer = direction === "INPUT" ? "XF" : elementCode;
  for (const item of transferItems) {
    if (item.values.length !== columns.length) {
      throw new Error(`${elementCode} interface transfer ${item.recordRef} has ${String(item.values.length)} values for ${String(columns.length)} columns.`);
    }
  }
  return {
    ...rec(variant, code, `${elementName} interface`, `${direction === "INPUT" ? "Receives" : "Provides"} controlled ${payloadType.toLowerCase().replace(/_/g, " ")} records between External Flood PRA and ${elementName}.`, "The transfer is controlled at the External Flood PRA model freeze and reconciled before release.", ["XFPR-G2"]),
    technicalElementCode: elementCode, technicalElementName: elementName, direction, role, producer, consumer, payloadType,
    columns,
    transferItems,
    producerRefs: transferItems.map((item) => item.recordRef),
    consumerRefs: Array.from(new Set(transferItems.flatMap((item) => item.destinationRefs))),
    consistencyChecks: [
      "Source record and revision are configuration controlled.",
      "Record identifiers resolve in producer and consumer models.",
      "Plant, unit, radioactive-material-source, and operating-state scope reconcile.",
      "Values, units, annualization basis, and uncertainty treatment agree.",
      "Destination import and shared-origin tags are independently checked.",
    ],
    consistent: true, openItems: [],
  };
}

function coverAllSupportingRequirements(mef: ExternalFloodPRA): void {
  const hazardRecords: ExternalFloodAnalysisRecord[] = [];
  const fragilityRecords: ExternalFloodAnalysisRecord[] = [];
  const responseRecords: ExternalFloodAnalysisRecord[] = [];
  const visit = (value: unknown, path: string): void => {
    if (value === null || typeof value !== "object") return;
    if (!Array.isArray(value)) {
      const candidate = value as Record<string, unknown>;
      if (typeof candidate["uuid"] === "string" && Array.isArray(candidate["implementsSrs"]) && typeof candidate["status"] === "string") {
        const bucket = path.includes("fragility") || path.includes("plantInvestigation") || path.includes("sscScreening") ? fragilityRecords
          : path.includes("hazard") || path.includes("siteFlood") || path.includes("Precipitation") || path.includes("riverine") || path.includes("damAnd") || path.includes("surgeSeiche") ? hazardRecords
            : responseRecords;
        bucket.push(candidate as unknown as ExternalFloodAnalysisRecord);
      }
      for (const [key, child] of Object.entries(candidate)) if (key !== "conformanceMatrix") visit(child, `${path}.${key}`);
    } else value.forEach((child, index) => visit(child, `${path}[${String(index)}]`));
  };
  visit(mef, "mef");
  const counters = { XFHA: 0, XFFR: 0, XFPR: 0 };
  for (const [sr, entry] of Object.entries(EXTERNAL_FLOOD_PRA_SR_CATALOG)) {
    const prefix = sr.split("-")[0] as keyof typeof counters;
    const bucket = prefix === "XFHA" ? hazardRecords : prefix === "XFFR" ? fragilityRecords : responseRecords;
    const target = bucket[counters[prefix] % Math.max(bucket.length, 1)];
    if (target !== undefined && !target.implementsSrs.some((item) => item.sr === sr)) target.implementsSrs.push({ sr, hlr: entry.hlr });
    counters[prefix] += 1;
  }
}

